package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.workflow.FormalEvaluationDelivery;
import com.ruoyi.medical.workflow.FormalEvaluationProtocol;
import java.time.LocalDateTime;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;

/** Immutable original dispatch + one durable network attempt. Unknown start never mints a new
 * command, reference or workflow. Acceptance requires actual original Temporal started evidence. */
public final class FormalEvaluationLaunchLedger {
    private final JdbcTemplate db;private final FormalEvaluationJobs jobs;private final PermissionSchema json;
    private final JsonMapper decoder=JsonMapper.builder().propertyNamingStrategy(com.fasterxml.jackson.databind.PropertyNamingStrategies.SNAKE_CASE).enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS,com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES).build();
    public FormalEvaluationLaunchLedger(DataSource data,FormalEvaluationJobs jobs,PermissionSchema json){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.jobs=jobs;this.json=json;}
    public record Configuration(String controlTaskQueue,String professionalTaskQueue,long activityTimeoutMillis,long heartbeatTimeoutMillis,long recoveryPollMillis) {
        public Configuration {for(String q:List.of(controlTaskQueue,professionalTaskQueue))if(!q.matches("[A-Za-z0-9_.-]{1,128}"))bad();if(controlTaskQueue.equals(professionalTaskQueue)||activityTimeoutMillis<1||activityTimeoutMillis>86400000||heartbeatTimeoutMillis<1||heartbeatTimeoutMillis>activityTimeoutMillis||recoveryPollMillis<100||recoveryPollMillis>60000)bad();}
    }
    public record Intent(FormalEvaluationJobs.Job job,String commandId,FormalEvaluationProtocol.Reference reference,String referenceSha256) {}
    public static final class Attempt {
        private final Intent intent;private final boolean first;private final AtomicBoolean consumed=new AtomicBoolean();
        private Attempt(Intent intent,boolean first){this.intent=intent;this.first=first;}
        public Intent intent(){return intent;}
        /** A second use is always read-only recovery, even before a process restart. */
        public boolean claimInitialSend(){return first&&consumed.compareAndSet(false,true);}
    }
    public Intent prepare(EnterpriseAccess.Admission a,FormalEvaluationJobs.Job expected,Configuration config)throws Exception {
        var job=jobs.byRun(a,expected.runId());same(expected,job);lock(job);
        var old=db.queryForList("SELECT run_id FROM formal_evaluation_launch_intent WHERE tenant_id=? AND run_id=? LIMIT 2",job.tenantId(),job.runId());if(!old.isEmpty())return original(a,job);
        var cell=jobs.cell(job);var steps=job.nodes().stream().sorted(Comparator.comparing(n->n.node().nodeKind())).map(n->new FormalEvaluationProtocol.Step(n.stepId(),n.node().nodeKind(),n.nodeSha256())).toList();
        var reference=new FormalEvaluationProtocol.Reference("1.0.0","SYSTEM_JOB","EVALUATION_VERIFICATION",job.tenantId(),job.projectId(),job.executionId(),cell.evaluationId(),job.runId(),cell.sampleId(),cell.repeatIndex(),cell.input().version_id(),cell.input().content_sha256(),job.admissionSha256(),cell.candidate().version_id(),cell.candidate().content_sha256(),cell.policy().version_id(),cell.policy().content_sha256(),steps,config.controlTaskQueue(),config.professionalTaskQueue(),config.activityTimeoutMillis(),config.heartbeatTimeoutMillis(),config.recoveryPollMillis());
        var state=one(db.queryForList("SELECT status,workflow_id,started_at,ended_at FROM system_job_run WHERE tenant_id=? AND run_id=? LIMIT 2",job.tenantId(),job.runId()));same("QUEUED",state.get("status"));if(state.get("workflow_id")!=null||state.get("started_at")!=null||state.get("ended_at")!=null)bad();
        String command=UUID.randomUUID().toString(),audit=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();var now=now();String hash=hash(json.tree(reference));var intent=new Intent(job,command,reference,hash);var evidence=event(intent,"PREPARED");journal(job,audit,event,"evaluation.launch.prepared",command,evidence,now);
        changed(db.update("INSERT INTO formal_evaluation_launch_intent(tenant_id,project_id,run_id,command_id,canonical_reference,reference_sha256,audit_id,event_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,?,?,'1.0.0',?,?,?,?)",job.tenantId(),job.projectId(),job.runId(),command,json.canonical(json.tree(reference)),hash,audit,event,json.manifestSha256(),job.actorId(),now,job.classification()));return original(a,job);
    }
    public Attempt attempt(EnterpriseAccess.Admission a,Intent expected)throws Exception {
        var original=original(a,expected.job());same(expected,original);lock(original.job());var job=original.job();
        var rows=db.queryForList("SELECT * FROM formal_evaluation_launch_attempt WHERE tenant_id=? AND run_id=? LIMIT 2",job.tenantId(),job.runId());if(!rows.isEmpty()){verifyAttempt(original,one(rows));return new Attempt(original,false);}
        var state=one(db.queryForList("SELECT status,workflow_id,started_at,ended_at FROM system_job_run WHERE tenant_id=? AND run_id=? LIMIT 2",job.tenantId(),job.runId()));same("QUEUED",state.get("status"));if(state.get("workflow_id")!=null||state.get("started_at")!=null||state.get("ended_at")!=null)bad();
        changed(db.update("INSERT INTO formal_evaluation_launch_attempt(tenant_id,project_id,run_id,command_id,reference_sha256,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,'1.0.0',?,?,?,?)",job.tenantId(),job.projectId(),job.runId(),original.commandId(),original.referenceSha256(),json.manifestSha256(),job.actorId(),now(),job.classification()));return new Attempt(original,true);
    }
    public Intent original(EnterpriseAccess.Admission a,FormalEvaluationJobs.Job expected)throws Exception {jobs.byRun(a,expected.runId());return originalFacts(a,expected);}
    private Intent originalFacts(EnterpriseAccess.Admission a,FormalEvaluationJobs.Job expected)throws Exception {
        var job=jobs.original(a,expected.runId());same(expected,job);var row=one(db.queryForList("SELECT * FROM formal_evaluation_launch_intent WHERE tenant_id=? AND run_id=? LIMIT 2",job.tenantId(),job.runId()));metadata(job,row);
        var reference=decoder.readValue(text(row,"canonical_reference"),FormalEvaluationProtocol.Reference.class);same(json.canonical(json.tree(reference)),text(row,"canonical_reference"));same(hash(json.tree(reference)),text(row,"reference_sha256"));
        var cell=jobs.cell(job);same(job.tenantId(),reference.tenantId());same(job.projectId(),reference.projectId());same(job.executionId(),reference.executionId());same(job.runId(),reference.runId());same(job.admissionSha256(),reference.admissionSha256());same(cell.evaluationId(),reference.evaluationId());same(cell.sampleId(),reference.sampleId());same(cell.repeatIndex(),reference.repeatIndex());same(cell.input().version_id(),reference.inputArtifactId());same(cell.input().content_sha256(),reference.inputSha256());same(cell.candidate().version_id(),reference.candidateVersion());same(cell.candidate().content_sha256(),reference.candidateSha256());same(cell.policy().version_id(),reference.policyVersion());same(cell.policy().content_sha256(),reference.policySha256());
        same(job.nodes().stream().sorted(Comparator.comparing(n->n.node().nodeKind())).map(n->new FormalEvaluationProtocol.Step(n.stepId(),n.node().nodeKind(),n.nodeSha256())).toList(),reference.steps());
        var intent=new Intent(job,text(row,"command_id"),reference,text(row,"reference_sha256"));WireValues.uuid(intent.commandId());verifyJournal(job,row,"evaluation.launch.prepared",intent.commandId(),event(intent,"PREPARED"));return intent;
    }
    /** Original recovery does not write an intent/attempt or reset the command. */
    public Intent recoveryOriginal(EnterpriseAccess.Admission a,FormalEvaluationJobs.Job job)throws Exception {var intent=original(a,job);verifyAttempt(intent,one(db.queryForList("SELECT * FROM formal_evaluation_launch_attempt WHERE tenant_id=? AND run_id=? LIMIT 2",job.tenantId(),job.runId())));return intent;}
    public JsonNode accepted(EnterpriseAccess.Admission a,Intent expected,FormalEvaluationDelivery.Accepted actual)throws Exception {
        var intent=recoveryOriginal(a,expected.job());same(expected,intent);same(intent.reference(),actual.reference());same(intent.commandId(),actual.commandId());var job=intent.job();lock(job);
        var receipt=event(intent,"ACCEPTED").put("workflow_id",actual.reference().workflowId()).put("temporal_run_id",actual.temporalRunId());
        var prior=db.queryForList("SELECT * FROM formal_evaluation_launch_receipt WHERE tenant_id=? AND run_id=? LIMIT 2",job.tenantId(),job.runId());if(!prior.isEmpty()){verifyReceipt(intent,one(prior),receipt);return receipt;}
        String audit=UUID.randomUUID().toString(),eventId=UUID.randomUUID().toString();var now=now();journal(job,audit,eventId,"evaluation.launch.accepted",intent.commandId(),receipt,now);
        changed(db.update("INSERT INTO formal_evaluation_launch_receipt(tenant_id,project_id,run_id,command_id,reference_sha256,workflow_id,temporal_run_id,canonical_receipt,receipt_sha256,audit_id,event_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,?,?,?,?,?,'1.0.0',?,?,?,?)",job.tenantId(),job.projectId(),job.runId(),intent.commandId(),intent.referenceSha256(),intent.reference().workflowId(),actual.temporalRunId(),json.canonical(receipt),hash(receipt),audit,eventId,json.manifestSha256(),job.actorId(),now,job.classification()));
        changed(db.update("UPDATE system_job_run SET workflow_id=?,status='RUNNING',started_at=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND run_id=? AND execution_kind='SYSTEM_JOB' AND job_type='EVALUATION_VERIFICATION' AND input_sha256=? AND status='QUEUED' AND workflow_id IS NULL AND started_at IS NULL AND ended_at IS NULL",intent.reference().workflowId(),now,now,job.tenantId(),job.projectId(),job.runId(),intent.reference().inputSha256()));
        requireAccepted(a,job,intent.reference());return receipt;
    }
    public void requireAccepted(EnterpriseAccess.Admission a,FormalEvaluationJobs.Job job,FormalEvaluationProtocol.Reference reference)throws Exception {
        var intent=recoveryOriginal(a,job);same(reference,intent.reference());var row=one(db.queryForList("SELECT * FROM formal_evaluation_launch_receipt WHERE tenant_id=? AND run_id=? LIMIT 2",job.tenantId(),job.runId()));var receipt=decoder.readTree(text(row,"canonical_receipt"));verifyReceipt(intent,row,receipt);
        if(one(db.query("SELECT COUNT(*) FROM system_job_run WHERE tenant_id=? AND project_id=? AND run_id=? AND workflow_id=? AND execution_kind='SYSTEM_JOB' AND job_type='EVALUATION_VERIFICATION' AND input_sha256=? AND started_at IS NOT NULL",(r,n)->r.getInt(1),job.tenantId(),job.projectId(),job.runId(),reference.workflowId(),reference.inputSha256()))!=1)bad();
    }
    public String requireOriginalAccepted(EnterpriseAccess.Admission a,FormalEvaluationJobs.Job job)throws Exception {
        var intent=originalFacts(a,job);verifyAttempt(intent,one(db.queryForList("SELECT * FROM formal_evaluation_launch_attempt WHERE tenant_id=? AND run_id=? LIMIT 2",job.tenantId(),job.runId())));
        var row=one(db.queryForList("SELECT * FROM formal_evaluation_launch_receipt WHERE tenant_id=? AND run_id=? LIMIT 2",job.tenantId(),job.runId()));verifyReceipt(intent,row,decoder.readTree(text(row,"canonical_receipt")));return text(row,"receipt_sha256");
    }
    private void verifyReceipt(Intent intent,Map<String,Object> row,JsonNode receipt)throws Exception {var job=intent.job();metadata(job,row);same(intent.commandId(),text(row,"command_id"));same(intent.referenceSha256(),text(row,"reference_sha256"));same(intent.reference().workflowId(),text(row,"workflow_id"));WireValues.uuid(text(row,"temporal_run_id"));same(event(intent,"ACCEPTED").put("workflow_id",intent.reference().workflowId()).put("temporal_run_id",text(row,"temporal_run_id")),receipt);same(json.canonical(receipt),text(row,"canonical_receipt"));same(hash(receipt),text(row,"receipt_sha256"));verifyJournal(job,row,"evaluation.launch.accepted",intent.commandId(),receipt);}
    private void verifyAttempt(Intent intent,Map<String,Object> row){metadata(intent.job(),row);same(intent.commandId(),text(row,"command_id"));same(intent.referenceSha256(),text(row,"reference_sha256"));}
    private com.fasterxml.jackson.databind.node.ObjectNode event(Intent i,String phase){return json.object().put("schema_version","1.0.0").put("kind","FORMAL_EVALUATION_LAUNCH_"+phase).put("execution_id",i.job().executionId()).put("run_id",i.job().runId()).put("command_id",i.commandId()).put("reference_sha256",i.referenceSha256()).put("admission_sha256",i.job().admissionSha256());}
    private void metadata(FormalEvaluationJobs.Job j,Map<String,Object> r){same(j.tenantId(),text(r,"tenant_id"));same(j.projectId(),text(r,"project_id"));same(j.runId(),text(r,"run_id"));same(j.actorId(),text(r,"created_by"));same(j.classification(),text(r,"classification"));same("1.0.0",text(r,"schema_version"));same(json.manifestSha256(),text(r,"schema_manifest_sha256"));if(r.get("created_at")==null)bad();}
    private void lock(FormalEvaluationJobs.Job j){one(db.queryForList("SELECT run_id FROM system_job_run WHERE tenant_id=? AND run_id=? FOR UPDATE",j.tenantId(),j.runId()));}
    private void journal(FormalEvaluationJobs.Job j,String audit,String event,String action,String command,JsonNode evidence,LocalDateTime now)throws Exception {changed(db.update("INSERT INTO audit_event(tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,'SUCCESS',?,?,'1.0.0',?,?,?,?)",j.tenantId(),j.projectId(),audit,j.actorId(),action,json.canonical(evidence),command,j.runId(),json.manifestSha256(),j.actorId(),now,j.classification()));changed(db.update("INSERT INTO outbox_event(tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES(?,?,?,1,?,?,?)",j.tenantId(),event,j.runId(),action,json.canonical(evidence),now));}
    private void verifyJournal(FormalEvaluationJobs.Job j,Map<String,Object> row,String action,String command,JsonNode evidence)throws Exception {same(json.canonical(evidence),one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND created_by=? AND action=? AND result='SUCCESS' AND request_id=? AND trace_id=? AND schema_version='1.0.0' AND schema_manifest_sha256=? AND classification=? AND created_at=? LIMIT 2",(r,n)->r.getString(1),j.tenantId(),j.projectId(),text(row,"audit_id"),j.actorId(),j.actorId(),action,command,j.runId(),json.manifestSha256(),j.classification(),row.get("created_at"))));same(json.canonical(evidence),one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND aggregate_revision=1 AND event_type=? AND occurred_at=? LIMIT 2",(r,n)->r.getString(1),j.tenantId(),text(row,"event_id"),j.runId(),action,row.get("created_at"))));}
    private LocalDateTime now(){return one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));}private String hash(JsonNode n)throws Exception{return WireValues.sha256(json.canonical(n).getBytes(java.nio.charset.StandardCharsets.UTF_8));}private static String text(Map<String,Object> r,String k){if(!(r.get(k) instanceof String))bad();return (String)r.get(k);}private static <T>T one(List<T> rows){if(rows.size()!=1||rows.get(0)==null)throw new TenantAccessException(ErrorCode.OBJECT_UNAVAILABLE);return rows.get(0);}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void changed(int n){if(n!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
